(()=>{document.addEventListener("DOMContentLoaded",()=>{let e=document.getElementById("toggle-menu"),s=document.getElementById("main-menu");if(!e||!s)return;let n=()=>{let t=document.body.classList.contains("show-menu");e.setAttribute("aria-expanded",String(t))};e.addEventListener("click",()=>{queueMicrotask(n)}),document.addEventListener("keydown",t=>{t.key!=="Escape"||!document.body.classList.contains("show-menu")||(e.click(),e.focus())}),window.addEventListener("resize",n),n()});})();
